import Foundation
import Testing
@testable import SkinKitRetroArch

/// The Swift converter against the website's JavaScript converter (skins#38), case by case.
///
/// `Fixtures/expected/` is generated by `scripts/gen-retroarch-expected.mjs` from the JS module; the `.cfg` and
/// `README.txt` must match it byte for byte, and the rest of the result (notes, skipped layouts, unconvertible
/// inputs, image plan, layout summary) field for field.
@Suite("RetroArch cfg parity with the JavaScript converter")
struct RetroArchParityTests {

    /// The converter's result minus the cfg text, in the shape the generator writes `<id>.json`.
    struct Summary: Codable, Equatable {
        struct Skipped: Codable, Equatable { var overlayName: String; var displayType: String; var asset: String; var reason: String }
        struct Unconvertible: Codable, Equatable {
            var `where`: String; var input: String; var reason: String
        }
        struct Rect: Codable, Equatable { var x: Double; var y: Double; var width: Double; var height: Double }
        struct Image: Codable, Equatable {
            var file: String; var kind: String; var asset: String?; var orientation: String; var overlayName: String
            var width: Double; var height: Double; var innerWidth: Double?; var innerHeight: Double?
            var clearRects: [Rect]
        }
        struct Size: Codable, Equatable { var width: Double; var height: Double }
        struct RectWH: Codable, Equatable { var x: Double; var y: Double; var w: Double; var h: Double }
        struct Layout: Codable, Equatable {
            var orientation: String; var overlayName: String; var set: String; var displayType: String
            var mapping: Size; var asset: String?; var rect: RectWH?
            var translucent: Bool; var screens: Int; var items: Int; var descs: Int
        }
        var name: String
        var system: String
        var device: String?
        var notes: [String]
        var skipped: [Skipped]
        var unconvertible: [Unconvertible]
        var descCount: Int
        var images: [Image]
        var layouts: [Layout]

        init(_ r: RetroArchConversion) {
            name = r.name
            system = r.system
            device = r.device
            notes = r.notes
            skipped = r.skipped.map { .init(overlayName: $0.overlayName, displayType: $0.displayType, asset: $0.asset, reason: $0.reason) }
            unconvertible = r.unconvertible.map { .init(where: $0.location, input: $0.input, reason: $0.reason) }
            descCount = r.descs.count
            images = r.images.map {
                .init(file: $0.file, kind: $0.kind.rawValue, asset: $0.asset, orientation: $0.orientation, overlayName: $0.overlayName,
                      width: $0.width, height: $0.height, innerWidth: $0.innerWidth, innerHeight: $0.innerHeight,
                      clearRects: $0.clearRects.map { .init(x: $0.x, y: $0.y, width: $0.width, height: $0.height) })
            }
            layouts = r.layouts.map {
                .init(orientation: $0.orientation, overlayName: $0.overlayName, set: $0.set, displayType: $0.displayType,
                      mapping: .init(width: $0.mappingWidth, height: $0.mappingHeight), asset: $0.asset,
                      rect: $0.rect.map { .init(x: $0.x, y: $0.y, w: $0.width, h: $0.height) },
                      translucent: $0.translucent, screens: $0.screens, items: $0.items, descs: $0.descs)
            }
        }
    }

    static let converter = try! RetroArchConverter.bundled()
    static let allCases = try! Fixture.cases()

    @Test("cfg and README match the JS output byte for byte", arguments: allCases)
    func cfgMatches(_ c: Fixture.Case) throws {
        let result = Self.converter.convert(try c.skinInfo(), options: c.options)
        #expect(result.cfg == (try Fixture.expectedText(c.id, "cfg")), "cfg differs for \(c.id)")
        #expect(result.readme == (try Fixture.expectedText(c.id, "README.txt")), "README differs for \(c.id)")
    }

    @Test("the report around the cfg matches the JS result", arguments: allCases)
    func reportMatches(_ c: Fixture.Case) throws {
        let result = Self.converter.convert(try c.skinInfo(), options: c.options)
        let expected = try JSONDecoder().decode(Summary.self, from: try Fixture.expected(c.id, "json"))
        #expect(Summary(result) == expected, "result differs for \(c.id)")
    }

    @Test("the cases cover every kind of control")
    func casesCoverControls() throws {
        let cfgs = try Self.allCases.map { try Fixture.expectedText($0.id, "cfg") }.joined()
        for needle in ["_next_target", "_reach_x", "_movable", "analog_left", "_rect = ", ",radial,", "l2", "menu_toggle", "up|left"] {
            #expect(cfgs.contains(needle), "no case exercises \(needle)")
        }
    }
}
